uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {}
vec3 shade(Led led) {
  float ang = atan2(led.uv.y - 0.5, led.uv.x - 0.5) / 6.2832;
  float hue = fract(ang * 4.0 + time * speed);
  return hsv2rgb(hue, 1.0, 1.0);
}

uniform float rate : 0.1 .. 3.0 = 0.6;
uniform vec3 base : color = 1.0, 0.3, 0.1;
state float glow;

void update() { glow = sin(time * rate); }

vec3 shade(Led led) { return mix(base, vec3(1.0), clamp(glow, 0.0, 1.0)); }

uniform float scale : 0.2 .. 4.0 = 1.0;
uniform float drift : 0.0 .. 2.0 = 0.3;

void update() {
}

vec3 shade(Led led) {
  float ang = atan2(led.pos.y, led.s - 0.5);
  float hue = fract(ang * scale + time * drift);
  return hsv2rgb(hue, 1.0, 1.0);
};

uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float width : 0.02 .. 0.5 = 0.12;
uniform vec3 tint : color = 0.2, 0.6, 1.0;

void update() {} 

vec3 shade(Led led) {
  float behind = fract(time * speed - led.s);
  return vec3(1.0, 0.8, 0.4) * exp(-8.0 * behind);
}

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {
}
vec3 shade(Led led) {
  vec3 base = mix(vec3(0.2, 0.4, 0.6), vec3(0.8, 0.9, 1.0), smoothstep(0.5, 1.0, time * speed));
  float noise = fract(sin(dot(imu.gyro, vec2(12.9898, 78.233))) * 4363.2);
  return mix(base, vec3(noise), step(time * speed - led.s, 0.5));
}

uniform float speed : 0.0 .. 5.0 = 1.0;
void update() {}
vec3 shade(Led led) {
  vec2 uv = led.uv;
  float t = fract(time * speed);
  return mix(vec3(0.0, 0.0, 0.0), vec3(1.0), step(t - 0.5, 0.0));
}

