uniform vec3 colorA : color = 1.0, 0.0, 0.0; // blue
uniform vec3 colorB : color = 1.0, 1.0, 1.0; // pink
uniform float start : 0.0 .. 255.0 = 0.0;
uniform float span : 1.0 .. 256.0 = 10.0;
float x = 0.0;
void update() {
    x += 0.1 * dt;
}

vec3 shade(Led led) {
    float t = clamp((led.idx - x) / max(span - 1.0, 1.0), 0.0, 1.0);
    return mix(colorA, colorB, t); 
}
